//! Offline paired floating-point/cost gates. No audio-thread admission.
pub use rf_d_circuit::*;
use std::{fs,time::Instant};
#[path="zero_baseline_kernel.rs"] mod baseline;
#[path="zero_scan_kernel.rs"] mod candidate;
struct Case{ohm:f64,h:f64,old:[f64;458],expected:[u64;1834],counts:[u64;2]}
fn scene()->conditioned_voice::Parameters{conditioned_recipe::Recipe{final_decay:conditioned_recipe::FinalDecay::On,resolution:conditioned_recipe::Resolution::Half2Us}.parameters()}
fn cases(path:&str)->Vec<Case>{let b=fs::read(path).unwrap();assert_eq!(&b[..8],b"RFPIVT01");let n=u32::from_le_bytes(b[8..12].try_into().unwrap()) as usize;assert_eq!(b.len(),12+n*18368);(0..n).map(|i|{let r=&b[12+i*18368..12+(i+1)*18368];let u=|k:usize|u64::from_le_bytes(r[8*k..8*k+8].try_into().unwrap());Case{ohm:f64::from_bits(u(0)),h:f64::from_bits(u(1)),old:std::array::from_fn(|k|f64::from_bits(u(k+2))),expected:std::array::from_fn(|k|u(k+460)),counts:[u(2294),u(2295)]}}).collect()}
macro_rules! runner{($name:ident,$module:ident)=>{
fn $name(cs:&[Case])->(u128,Vec<(Vec<u64>,[u64;2])>){let mut w=$module::Workspace::new();let mut time=0;let mut rows=Vec::new();for c in cs{let mut p=$module::Parameters::from_nominal(scene());p.decay_ohm=c.ohm;let s=$module::State{high:std::array::from_fn(|k|c.old[k]),low:std::array::from_fn(|k|c.old[k+229])};let t=Instant::now();let a=w.step(p,s,c.h).expect("finite native pair");time+=t.elapsed().as_nanos();let mut v=Vec::new();for state in a.increments.iter().chain(a.candidates.iter()){v.extend(state.high.iter().chain(state.low.iter()).map(|v|v.to_bits()));}v.extend([a.residual_ratio.to_bits(),a.correction_ratio.to_bits()]);assert_eq!(v,c.expected,"historical 1834 fields");let counts=[a.iterations as u64,a.trials as u64];if c.counts[0]!=u64::MAX{assert_eq!(counts,c.counts);}rows.push((v,counts));}(time,rows)}
}}
runner!(run_baseline,baseline);runner!(run_candidate,candidate);
fn ieee(){
 let vals=[0.,-0.,f64::from_bits(1),-f64::from_bits(1),1e-308,-1e-308,1.,-1.,f64::MAX,-f64::MAX];let mut count=0;let mut rejects=0;
 for seed in 0..128{let j=std::array::from_fn(|r|std::array::from_fn(|c|if r==c{if seed%16==0{0.5}else{2.}}else{match(seed+3*r+5*c)%7{0=>-0.,1=>0.25,2=>-0.25,3=>1e-308,_=>0.}}));for phase in 0..10{let b=std::array::from_fn(|r|vals[(phase+3*r)%10]);let a=baseline::dynamic_schur::rhs_probe(j,b);let b=candidate::dynamic_schur::rhs_probe(j,b);assert_eq!(a,b,"IEEE private LU fixture {seed}/{phase}");if a.is_err(){rejects+=1;}count+=1;}}
 let j=std::array::from_fn(|r|std::array::from_fn(|c|if r==c{1.}else{0.}));let dense=baseline::dynamic_schur::rhs_probe(j,[-0.;4]).unwrap();assert_eq!(dense,candidate::dynamic_schur::rhs_probe(j,[-0.;4]).unwrap());assert_ne!(dense,[-0_f64;4].map(f64::to_bits),"blind omission loses zero sign");println!("IEEE_PASSED,{count},rejects={rejects},signed_zero_control=1");
 println!("STORAGE,{},{}",baseline::dynamic_schur::scratch_bytes(),candidate::dynamic_schur::scratch_bytes());
}
fn errors(){for kind in 0..6{let mut j=[[0.;458];458];let mut b=[0.;458];for k in 0..458{j[k][k]=1.;b[k]=1.;}match kind{0=>j.fill([0.;458]),1=>j[0][0]=f64::NAN,2=>b[0]=f64::INFINITY,3=>j[56][0]=1.,4=>{j[0][1]=1.;j[1][0]=1.;j[1][1]=1.+1e-14;},_=>{b[0]=f64::MAX;j[0][0]=0.1;}}let a=baseline::dynamic_schur::solve_observed(j,b).err();let c=candidate::dynamic_schur::solve_observed(j,b).err();assert!(a.is_some());assert_eq!(a,c,"same full solver error class");}println!("ERRORS_PASSED,6");}
fn stamps(cs:&[Case]){for c in cs{let mut p=baseline::Parameters::from_nominal(scene());p.decay_ohm=c.ohm;let mut q=candidate::Parameters::from_nominal(scene());q.decay_ohm=c.ohm;let o=baseline::State{high:std::array::from_fn(|k|c.old[k]),low:std::array::from_fn(|k|c.old[k+229])};let co=candidate::State{high:o.high,low:o.low};let d=std::array::from_fn(|i|baseline::State{high:std::array::from_fn(|k|f64::from_bits(c.expected[i*458+k])),low:std::array::from_fn(|k|f64::from_bits(c.expected[i*458+229+k]))});let cd=std::array::from_fn(|i|candidate::State{high:d[i].high,low:d[i].low});let a=baseline::linearize(p,o,d,c.h).unwrap();let b=candidate::linearize(q,co,cd,c.h).unwrap();assert!(a.residual.iter().chain(a.jacobian.iter().flatten()).chain(a.candidates.iter().flat_map(|s|s.high.iter().chain(s.low.iter()))).zip(b.residual.iter().chain(b.jacobian.iter().flatten()).chain(b.candidates.iter().flat_map(|s|s.high.iter().chain(s.low.iter())))).all(|(a,b)|a.to_bits()==b.to_bits()));}println!("STAMPS_PASSED,168,211138");}
fn main(){let args:Vec<_>=std::env::args().collect();let cs=cases(&args[1]);assert_eq!(cs.len(),168);ieee();errors();stamps(&cs);let(_,gold)=run_baseline(&cs);for round in 0..5{let(a,x,b,y)=if round%2==0{let(a,x)=run_baseline(&cs);let(b,y)=run_candidate(&cs);(a,x,b,y)}else{let(b,y)=run_candidate(&cs);let(a,x)=run_baseline(&cs);(a,x,b,y)};assert_eq!(gold,x);assert_eq!(gold,y);println!("ROUND,{round},{a},{b}");}println!("ZERO_SCAN_BENCH_PASSED,168,1834,5");}
